const item = $input.first().json;

// Détecter si l'entrée provient du formulaire manuel ou du webhook boutique
const isWebhook = !!item.body;
const data = isWebhook ? item.body : item;

const campaignType = data['Type de Campagne'] || (data.products && data.products.length > 1 ? 'multi' : (data['Produit 2 - Nom'] ? 'multi' : 'mono'));
const generalTitle = data['Titre Général ou Arrivage'] || data.title || 'ARRIVAGE EXCLUSIF';
const whatsapp = data['Numéro WhatsApp VVS'] || '+225 05 04 59 45 20';
const notifyPhone = data['Numéro WhatsApp pour Notification / Validation'] || '2250504594520';
const delivery = data['Rassurance Livraison'] || '🚚 Livraison 24h|Abidjan & Partout en CI';
const payment = data['Rassurance Paiement'] || '💵 Paiement à la Livraison|Vérifiez avant de payer';
const autoRembg = data["Détourer Automatiquement les Photos (Rembg)"] === 'true' || data.autoRembg === true;
const audience = data['Modèle Humain (Si Mono-Produit)'] || data.audience || 'homme_barbe';

const products = [];

if (data['Produit 1 - Nom'] || data.productName) {
  const name = data['Produit 1 - Nom'] || data.productName;
  const price = data['Produit 1 - Prix en FCFA'] || data.price || 'Prix sur demande';
  const rawSpecs = data['Produit 1 - Fiche Technique & Points Clés'] || data.specs || data.description || '';
  const specs = typeof rawSpecs === 'string' ? rawSpecs.split(/[,\n]/).map(s => s.trim()).filter(Boolean) : rawSpecs;
  const img = data['Produit 1 - Chemin ou URL Image'] || data.image || '';
  products.push({ name, price, specs, image: img, tag: 'Bureautique Pro', featured: false });
}

if (data['Produit 2 - Nom']) {
  const name = data['Produit 2 - Nom'];
  const price = data['Produit 2 - Prix en FCFA'] || '';
  const rawSpecs = data['Produit 2 - Fiche Technique'] || '';
  const specs = rawSpecs.split(/[,\n]/).map(s => s.trim()).filter(Boolean);
  const img = data['Produit 2 - Chemin ou URL Image'] || '';
  products.push({ name, price, specs, image: img, tag: '⭐ Coup de Cœur', featured: true });
}

if (data['Produit 3 - Nom']) {
  const name = data['Produit 3 - Nom'];
  const price = data['Produit 3 - Prix en FCFA'] || '';
  const rawSpecs = data['Produit 3 - Fiche Technique'] || '';
  const specs = rawSpecs.split(/[,\n]/).map(s => s.trim()).filter(Boolean);
  const img = data['Produit 3 - Chemin ou URL Image'] || '';
  products.push({ name, price, specs, image: img, tag: 'Ultra-Nomade', featured: false });
}

const isMulti = campaignType === 'multi' || products.length > 1;

return {
  json: {
    isMulti,
    campaignType,
    generalTitle,
    products,
    whatsapp,
    notifyPhone,
    delivery,
    payment,
    autoRembg,
    audience,
    productsCount: products.length,
    productsSummary: products.map(p => `- ${p.name} (${p.price}) : ${(p.specs || []).join(', ')}`).join('\n')
  }
};

