parameters.jsCode:
const fs = require('fs');
const path = require('path');
const os = require('os');

const geminiRes = $input.first().json;
const meta = $('2. Formatage & Normalisation').first().json;

let parsed = {};
try {
  const rawText = geminiRes.candidates[0].content.parts[0].text;
  parsed = JSON.parse(rawText);
} catch (e) {
  parsed = {
    headline: meta.generalTitle || 'ARRIVAGE EXCLUSIF',
    subtitle: 'Performance, Robustesse & Garantie au Meilleur Prix',
    flashBadge: '🔥 ARRIVAGE EXCLUSIF • QUANTITÉS LIMITÉES 🔥',
    adCopyFacebook: 'Découvrez notre sélection spéciale au meilleur prix du marché !'
  };
}

const tmpDir = os.tmpdir();
const configJsonPath = path.join(tmpDir, `multi_prod_config_${Date.now()}.json`);
fs.writeFileSync(configJsonPath, JSON.stringify(meta.products, null, 2), 'utf8');

const finalPosterPath = path.join(tmpDir, `affiche_multi_vvs_${Date.now()}.png`);

return {
  json: {
    ...meta,
    headline: parsed.headline,
    subtitle: parsed.subtitle,
    flashBadge: parsed.flashBadge,
    adCopyFacebook: parsed.adCopyFacebook,
    configJsonPath: configJsonPath.replace(/\\/g, '/'),
    finalPosterPath: finalPosterPath.replace(/\\/g, '/')
  }
};

